import os, math, subprocess, nbformat as nbf
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
ov = lambda z: math.exp(-math.pi * z / math.sqrt(1 - z * z)) * 100 if z < 1 else 0.0
def build(lang):
    vi = lang == 'vi'; T = lambda a, b: a if vi else b; nb = nbf.v4.new_notebook(); C = []
    md = lambda s: C.append(nbf.v4.new_markdown_cell(s)); code = lambda s: C.append(nbf.v4.new_code_cell(s))
    md(T('# Module 10 · Servo và synchro (EASA M04 SM03 + giáo trình servo)', '# Module 10 · Servomechanisms and synchros (EASA M04 SM03 + the servo text)'))
    code('import numpy as np, matplotlib\nmatplotlib.use("Agg")\nimport matplotlib.pyplot as plt\n%matplotlib inline')
    md(T('## 1. Điện áp ba cuộn stato theo góc rôto', '## 1. The three stator coil voltages versus rotor angle'))
    code('Vr = 115.0; Vmax = Vr/2.2     # SV p.14: 2.2:1 step-down, ~52 V\nth = np.radians(np.arange(0, 361, 30)); phases = np.radians([0, 120, 240])\nprint(f"Vmax per coil = {Vmax:.1f} V")\nfor t in (0, 30, 60, 90, 120):\n    v = Vmax*np.cos(np.radians(t) - phases); print(f"rotor {t:>3} deg: S-coil voltages = {np.round(v,1)}  (sum = {v.sum():.1f})")\nang = np.linspace(0, 360, 361)\nfor k, ph in enumerate(phases): plt.plot(ang, Vmax*np.cos(np.radians(ang)-ph), label=f"coil {k+1}")\nplt.legend(); plt.xlabel("rotor angle (deg)"); plt.ylabel("V"); plt.grid(alpha=.3); plt.show()')
    md(T('**Nhận xét:** mỗi cuộn đạt tối đa ≈ 52,3 V khi rôto thẳng hàng với nó; tại mọi góc ba điện áp có tổng bằng không (mô hình lý tưởng) và cặp giá trị xác định duy nhất góc — vì thế ba dây đủ để truyền góc.', '**Comment:** each coil peaks at ≈ 52.3 V when the rotor lines up with it; at every angle the three voltages sum to zero (ideal model) and the set uniquely identifies the angle — which is why three wires are enough to transmit it.'))
    md(T('## 2. Điện áp sai số của CT và độ nhạy gần null', '## 2. CT error voltage and sensitivity near the null'))
    code('Emax = 55.0     # SV p.35: maximum 55 V when the CT rotor is parallel to the stator field\nfor d in (0, 1, 5, 10, 30, 60, 90): print(f"misalignment {d:>2} deg: error = {Emax*np.sin(np.radians(d)):6.2f} V (small-angle approx {Emax*np.radians(d):6.2f} V)")\nang = np.linspace(-180, 180, 361); plt.plot(ang, Emax*np.sin(np.radians(ang))); plt.xlabel("misalignment (deg)"); plt.ylabel("error voltage (V)"); plt.grid(alpha=.3); plt.show()')
    md(T('**Nhận xét:** mô hình Verr = 55·sin(Δθ) cho 0,96 V ở 1°, 4,79 V ở 5°, và 55 V ở 90°; gần null độ dốc ≈ 0,96 V/độ nên CT phát hiện rất nhạy độ lệch nhỏ; phép xấp xỉ góc nhỏ sai dưới 1 % cho tới 10°. (Giá trị 55 V lấy từ ví dụ SV; quy luật sin là mô hình lý tưởng.)', '**Comment:** the model Verr = 55·sin(Δθ) gives 0.96 V at 1°, 4.79 V at 5° and 55 V at 90°; near the null the slope is ≈ 0.96 V/deg so the CT detects small errors very sensitively; the small-angle approximation is off by less than 1 % up to 10°. (The 55 V comes from the SV example; the sine law is an ideal model.)'))
    md(T('## 3. Servo vận tốc: ví dụ của SV tr.71', '## 3. The velocity servo: SV p.71 example'))
    code('K, t, Vin = 10.0, 0.1, 9.0       # 10 rpm per volt of error, tach 0.1 V/rpm, control -9 V, R2=R3\nN = 0.0; hist = []\nfor k in range(60):\n    err = (Vin - t*N)/2           # sum point magnitude\n    N += 0.3*(K*err - N)           # motor speed follows K*err with a first-order lag\n    hist.append((N, err))\nprint(f"first instant error = {Vin/2:.2f} V")\nprint(f"after 60 steps: N = {hist[-1][0]:.2f} rpm, error = {hist[-1][1]:.2f} V")\nprint(f"analytic: N = K*Vin/(2+K*t) = {K*Vin/(2+K*t):.2f} rpm, error = {K*Vin/(2+K*t)/K:.2f} V")\nplt.plot([h[0] for h in hist]); plt.xlabel("step"); plt.ylabel("speed (rpm)"); plt.grid(alpha=.3); plt.show()')
    md(T('**Nhận xét:** sai số ban đầu 4,5 V, tốc độ tiến đến 30 vòng/phút và sai số 3 V, đúng ví dụ của giáo trình; ở cân bằng vẫn còn sai số 3 V — đặc điểm của servo vận tốc.', '**Comment:** the initial error is 4.5 V, the speed converges to 30 rpm and the error to 3 V, exactly as in the text; at balance an error of 3 V remains — the signature of a velocity servo.'))
    md(T('## 4. Hunting và tắt dần của servo vị trí', '## 4. Hunting and damping of a position servo'))
    zs = [0.05, 0.7, 1.2]
    code('J, B, KtKp = 1.0, 0.2, 4.0      # inertia, friction, loop gain\nwn = np.sqrt(KtKp/J)\ndt = 1e-3; T = np.arange(0, 12, dt)\nres = {}\nfor name, Kd in (("no damping", 0.0), ("tach damping", 2.6), ("heavy damping", 4.6)):\n    z = (B + Kd)/(2*np.sqrt(KtKp*J)); th = 0.0; w = 0.0; y = []\n    for _ in T:\n        e = 1.0 - th; acc = (KtKp*e - Kd*w - B*w)/J; w += acc*dt; th += w*dt; y.append(th)\n    y = np.array(y); res[name] = (z, (y.max()-1)*100); plt.plot(T, y, label=f"{name} (zeta={z:.2f})")\n    print(f"{name:14s}: zeta = {z:.2f}, simulated overshoot = {max(0,(y.max()-1)*100):5.1f} %, formula = {(np.exp(-np.pi*z/np.sqrt(1-z*z))*100 if z<1 else 0):5.1f} %")\nplt.axhline(1, color="gray", lw=.8); plt.legend(); plt.xlabel("t (s)"); plt.grid(alpha=.3); plt.show()')
    md(T(f'**Nhận xét:** không có tắt dần ζ = {zs[0]} và vượt quá khoảng {ov(0.05):.0f} % rồi dao động kéo dài (hunting); tắt dần bằng hồi tiếp máy phát tốc đưa ζ lên {zs[1]} với vượt quá khoảng {ov(0.7):.1f} %; tắt dần mạnh ζ = {zs[2]} không còn vượt quá — đúng tinh thần quá/thiếu tắt dần trong SV tr.73.', f'**Comment:** with no damping ζ = {zs[0]} and the overshoot is about {ov(0.05):.0f} % with long-lasting oscillation (hunting); tachometer-feedback damping raises ζ to {zs[1]} with about {ov(0.7):.1f} % overshoot; heavy damping ζ = {zs[2]} has no overshoot — in line with over/underdamping in SV p.73.'))
    nb['cells'] = C; return nb
if __name__ == '__main__':
    for lang in ('vi', 'en'):
        p = os.path.join(ROOT, 'notebooks', f'm10_servomechanisms_{lang}.ipynb'); nbf.write(build(lang), p)
        subprocess.run(['jupyter', 'nbconvert', '--to', 'notebook', '--execute', '--inplace', p], check=True, capture_output=True); print('executed', p)
